def perguntar(p):
    def gerar():
        try:
            yield from stream(PRIMARIO, p.texto)
        except anthropic.APIStatusError as e:
            # só refaz em 429 ou 5xx (não 4xx)
            if e.status_code in (429, 500, 503):
                yield from stream(FALLBACK, p.texto)
            else:
                raise
    return StreamingResponse(gerar())
